mapper.select:
SELECT t.id, t.task_no, t.task_type, t.status, t.warehouse_id, w.name AS warehouse_name, t.sku_id, p.sku_code, p.name AS sku_name, t.batch_no, t.from_location_id, fl.code AS from_location_code, t.to_location_id, tl.code AS to_location_code, t.plan_qty, t.actual_qty, t.assignee_id, t.assignee_name, t.source_type, t.source_id, t.source_no, t.priority, t.create_time, t.start_time, t.finish_time, t.remark FROM stock_task t LEFT JOIN warehouse w ON w.id = t.warehouse_id AND w.deleted = 0 LEFT JOIN location fl ON fl.id = t.from_location_id LEFT JOIN location tl ON tl.id = t.to_location_id LEFT JOIN product p ON p.id = t.sku_id WHERE t.deleted = 0
AND (t.task_no LIKE CONCAT('%', #{query.keyword}, '%') OR p.sku_code LIKE CONCAT('%', #{query.keyword}, '%') OR p.name LIKE CONCAT('%', #{query.keyword}, '%'))
AND t.task_type = #{query.taskType}
AND t.status = #{query.status}
AND t.warehouse_id = #{query.warehouseId}
AND t.assignee_id = #{query.assigneeId}
AND t.source_no = #{query.sourceNo}
AND t.create_time >= #{query.beginTime}
AND t.create_time < DATE_ADD(#{query.endTime}, INTERVAL 1 DAY)
ORDER BY (t.status IN ('DONE', 'CANCELLED', 'TIMEOUT')) ASC, t.id DESC

mapper.update:
UPDATE stock_task SET status = 'DONE', actual_qty = #{actualQty}, finish_time = NOW(3)
, remark = #{remark}
WHERE id = #{id} AND status = 'PROCESSING' AND deleted = 0
